(* [comment removed for export] *)
Lemma s_call_pC M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 (fx1 : FPState) R1 (QPC QSCR QMX ra so : Z) (Qneed : Z -> Z)
      (qpre : bvmap 5 word -> mem -> list fframe -> Z -> Z -> Z -> Prop) (qpost : bvmap 5 word -> Prop) (bs : list Z) :
  VAC.pusherAC RSEGS AD L ar HI QPC QSCR Qneed (VA.ERRNO_W (pa_tp AD)) QMX qpre qpost ->
  0 <= QSCR -> QSCR mod 16 = 0 -> sp - SCR <= spc - QSCR -> 0 <= QMX ->
  (forall j, In j PQRA.FCM -> Qneed j + (if k =? j then 1 else 0) <= PNVA.VIS_H) ->
  a_mem M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 ->
  getr R1 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> getr R1 (reg 2) = Z_to_bv 64 spc ->
  getr R1 (reg 3) = Z_to_bv 64 (pa_gp AD) -> getr R1 (reg 4) = Z_to_bv 64 (hl_tp L) ->
  spc <= so -> so + 8 <= olo -> so mod 8 = 0 -> L5.u64_at RSEGS M1 so (oa + PQMA.AOFF_KEY) ->
  qpre R1 M1 FF' so (oa + PQMA.AOFF_KEY) spc ->
  PM.vs_size (PQMA.a_key st1) + QMX <= PQMA.SMK ->
  NEM.kcontent RSEGS M1 (oa + PQMA.AOFF_KEY) (PQMA.a_key st1) bs ->
  (forall (fx2 : FPState) R2 (M3 : mem) model3 LK3 Aw3 x' g' cr3 (ds : list Z),
      regs_preserved R1 R2 -> qpost R2 ->
      a_mem M3 model3 LK3 Aw3 (s_set true st1 x' g') eso1 qe1 cr3 ->
      PM.vs_size (PQMA.a_key st1) <= PM.vs_size x' <= PM.vs_size (PQMA.a_key st1) + QMX ->
      NEM.kcontent RSEGS M3 (oa + PQMA.AOFF_KEY) x' (bs ++ ds) -> NEM.ascii ds ->
