Section UFrame.
Variables (spc olo ohi : Z) (ocell : Z -> Prop) (own : mem -> Prop) (k F fl : Z) (LK2 : list fframe) (M2 : mem) (model2 : Model).
Hypothesis G : PMAUK.gctx L ar HI LB FF LK Aw sp SCR spc olo ohi ocell own F fl k LK2 M2 model2 cr BX0.
Hypothesis APART : forall a n0 sp0 scr0, (forall i, 0 <= i < n0 -> aclient L ar (BX0 ++ LB) FF sp0 scr0 (a + i)) -> 0 < n0 ->
         (a + n0 <= F \/ F + ff_bytes k <= a) /\ (a + n0 <= F / 8 + SB \/ F / 8 + SB + ff_bytes k / 8 <= a) /\ (a + n0 <= fl \/ fl + 1 <= a).
Hypothesis HSPC : sp - SCR + 512 <= spc /\ spc mod 16 = 0.
Local Notation B := (ff_bytes k).
Local Notation FF' := ((F, k, spc + 32) :: FF).
Local Notation GM := (VAKU.g_mem L ar HI M model LB FF LK Aw sp SCR WT spc own k F).
Local Notation "'GF' f" := (f L ar C HI LY HIok K R M model LB FF LK Aw cr sp r SCR need BX0 WT HH AM K0 ENT FRM FRS HSCR NEED0 wapp_T spc olo ohi ocell own k F fl LK2 M2 model2 G APART HSPC)
  (at level 10, f at level 9, only parsing).

(* [comment removed for export] *)
Definition uinv (n : Z) (M1 : mem) (model1 : Model) (LK1 : list fframe) (Aw1 : list (Z * Z)) (x : PM.vstr) (g1 : Z) (cr1 : credit) : Prop :=
  GM (PM.vs_own x) M1 model1 LK1 Aw1 cr1 /\
  kstr_at M1 os x /\ PQMA.ks_ok SM x g1 /\ PM.vs_size x = PM.vs_size x0 + n /\
  PMSTA.base_okA RSEGS AD M1 /\
  PMSP.credit_keep cr cr1 POT0 (PMSPA.scA L (PQMA.pot_ks HV SM x g1)).

