(* [comment removed for export] *)
Lemma u_callee n M1 model1 LK1 Aw1 x g1 cr1 R1 (ra SCRc : Z) (needc : Z -> Z) :
  uinv n M1 model1 LK1 Aw1 x g1 cr1 -> 0 <= SCRc -> SCRc mod 16 = 0 -> sp - SCR <= spc - SCRc ->
  (forall j, In j PQRA.FCM -> needc j + (if k =? j then 1 else 0) <= need j) ->
  getr R1 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> getr R1 (reg 2) = Z_to_bv 64 spc ->
  getr R1 (reg 3) = Z_to_bv 64 (pa_gp AD) -> getr R1 (reg 4) = Z_to_bv 64 (hl_tp L) ->
  (VA.entryAs AD L ar R1 M1 spc ra SCRc /\ VA.ffroomN needc FF' LK1 /\ PMSPA.ffrsA FF' spc /\ spc mod 16 = 0)
  /\ (VA.rcellA ar M1 spc so 8 /\ L5.u64_at RSEGS M1 so os /\ PMSPA.aobjA FF' os 24)
  /\ (ri_inv HI (PM.vs_own x ++ LB) FF' LK1 cr1 Aw1 M1 (vml_of model1) /\ L5CA.amodel_ok Aw1 model1 /\ kstr_at M1 os x /\ PQMA.ks_ok SM x g1
      /\ PMSTA.base_okA RSEGS AD M1 /\ PMSP.credit_le (PMSPA.scA L (PQMA.pot_ks HV SM x g1)) cr1).
Proof using All.
