(* [comment removed for export] *)
Lemma UCALL n M1 model1 LK1 Aw1 x g1 cr1 (fx1 : FPState) R1 (ra c : Z) :
  uinv n M1 model1 LK1 Aw1 x g1 cr1 -> 0 <= n < MAX -> sp - SCR <= spc - 14336 ->
  (forall j, In j PQRA.FCM -> 1 + (if k =? j then 1 else 0) <= need j) ->
  getr R1 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> getr R1 (reg 2) = Z_to_bv 64 spc ->
  getr R1 (reg 3) = Z_to_bv 64 (pa_gp AD) -> getr R1 (reg 4) = Z_to_bv 64 (hl_tp L) ->
  getr R1 (reg 10) = Z_to_bv 64 os -> getr R1 (reg 11) = Z_to_bv 64 c -> 0 <= c < 256 ->
  (forall (fx2 : FPState) R2 (M3 : mem) model3 LK3 Aw3 x3 g3 cr3,
      regs_preserved R1 R2 -> uinv (n + 1) M3 model3 LK3 Aw3 x3 g3 cr3 ->
      (forall a, spc <= a < sp -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      (forall a, F <= a < F + B - 8 -> ~ (F + 24 <= a < F + 32) -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      (forall a, F / 8 + SB <= a < F / 8 + SB + B / 8 -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 ra M3 model3) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 PBPC M1 model1) K.
