(* [comment removed for export] *)
Section PCall.
Variables (QPC QSCR : Z) (Qneed : Z -> Z) (QW : list L5.range) (QMX : Z) (qpre : bvmap 5 word -> mem -> list fframe -> Z -> Z -> Z -> Prop) (qpost : bvmap 5 word -> Prop).
Hypothesis Q : VA.pusherA RSEGS AD L ar HI QPC QSCR Qneed QW QMX qpre qpost.
Hypothesis QSCR16 : 0 <= QSCR /\ QSCR mod 16 = 0.
Hypothesis QMX0 : 0 <= QMX.
Hypothesis QNEED : forall j, In j PQRA.FCM -> Qneed j + (if k =? j then 1 else 0) <= need j.
Hypothesis QWW : forall a, L5.outside W a -> L5.outside QW a.

Lemma UCALLP n M1 model1 LK1 Aw1 x g1 cr1 (fx1 : FPState) R1 (ra : Z) :
  uinv n M1 model1 LK1 Aw1 x g1 cr1 -> 0 <= n -> n + QMX <= MAX -> sp - SCR <= spc - QSCR ->
  getr R1 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> getr R1 (reg 2) = Z_to_bv 64 spc ->
  getr R1 (reg 3) = Z_to_bv 64 (pa_gp AD) -> getr R1 (reg 4) = Z_to_bv 64 (hl_tp L) ->
  qpre R1 M1 FF' so os spc ->
  (forall (fx2 : FPState) R2 (M3 : mem) model3 LK3 Aw3 x3 g3 cr3 (n' : Z),
      regs_preserved R1 R2 -> qpost R2 -> n <= n' <= n + QMX -> uinv n' M3 model3 LK3 Aw3 x3 g3 cr3 ->
      (forall a, spc <= a < sp -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      (forall a, F <= a < F + B - 8 -> ~ (F + 24 <= a < F + 32) -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      (forall a, F / 8 + SB <= a < F / 8 + SB + B / 8 -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 ra M3 model3) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 QPC M1 model1) K.
