(* [comment removed for export] *)
Section Kit.
(* [comment removed for export] *)
Variables (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet) (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit).
Variables (sp r ov osk : Z) (en : enc) (k : NESK.sink) (h SCR FR : Z).

Definition kctx : Prop :=
  NESKA.spa_hb P NESK.SMZ /\ PMSPA.pm_scr h = SCR /\ 0 <= h
  /\ ri_inv HI (NECS.eown en k ++ LBX) FF LK cr Aw M (vml_of model) /\ L5CA.amodel_ok Aw model /\ K []
  /\ PMSPA.entryA AD L ar R M sp r h /\ PMSPA.ffroomA h FF LK /\ PMSPA.ffrsA FF sp /\ sp mod 16 = 0
  /\ PMSPA.aobjA FF ov 56 /\ ov mod 8 = 0 /\ PMSPA.aobjA FF osk 24 /\ osk mod 8 = 0 /\ (ov + 56 <= osk \/ osk + 24 <= ov)
  /\ enc_atA L ar M ov osk en /\ sink_atA L ar P M osk k
  /\ PMSP.credit_le (NESKA.spa_pot P (NESK.sk_c k)) cr
  /\ FR mod 16 = 0 /\ 16 <= FR /\ FR + 16384 <= SCR.
Hypothesis CX : kctx.
(* [comment removed for export] *)
#[local] Set Default Proof Using "All".
Local Ltac getctx :=
  pose proof CX as (HBS & HSCR & H0 & HH & AM & K0 & ENT & FRM & FRS & SP16 & AOov & ALov & AOosk & ALosk & SEP & EA & SKA & CRED & FR16 & FRlo & FRhi).
Local Ltac entry_facts :=
  pose proof CX as (HBS & HSCR & H0 & HH & AM & K0 & ENT & FRM & FRS & SP16 & AOov & ALov & AOosk & ALosk & SEP & EA & SKA & CRED & FR16 & FRlo & FRhi);
  pose proof ENT as (Rra & RAok & Rsp & Rgp & Rtp & ASTK & STKSH); rewrite HSCR in ASTK, STKSH;
  pose proof ASTK as (A16 & SLO & SHI & SPT & SDEF & SUP); pose proof RAok as (Hr1 & Hr2);
  rewrite L5K.rl1 in Rra; rewrite L5K.rl2 in Rsp; rewrite L5K.rl3 in Rgp; rewrite L5K.rl4 in Rtp;
  pose proof (HAJ.aior_wf _ _ _ _ _ HIok _ _ _ _ _ _ _ HH) as (WB & WF & FSAPP & FSCEIL & FSIMG & FSSH & STSH & _ & _ & STOP & ND & _).

Let LB : list (Z * Z) := NECS.eown en k ++ LBX.
Let LBY : list (Z * Z) := enc_own en ++ LBX.
Let Ws : list L5.range := [(osk, 24)].

