(* [comment removed for export] *)
(* [comment removed for export] *)
Definition cinv (cells : list (Z * Z)) (Mi : word -> option byte) (mdi : Model) (LKi : list fframe) (Awi : list (Z * Z)) (cri : credit) (ki : NESK.sink) (lo hi : Z) : Prop :=
  Forall (fun c => L5.u64_at RSEGS Mi (fst c) (snd c)) cells
  /\ L5CA.astk ar Mi sp SCR /\ shadow_zero Mi (sp - SCR) (SCR / 8)
  /\ model_rt model mdi /\ L5CA.amodel_ok Awi mdi /\ incl LKi LK /\ incl Aw Awi
  /\ ri_inv HI (NECS.eown en ki ++ LBX) FF LKi cri Awi Mi (vml_of mdi)
  /\ enc_atA L ar Mi ov osk en /\ sink_atA L ar P Mi osk ki
  /\ NESK.sk_z k + lo <= NESK.sk_z ki <= NESK.sk_z k + hi
  /\ L5SAR.ek L ar LBX FF sp SCR Ws M Mi /\ L5SAR.dk L ar LBX FF sp SCR M Mi
  /\ PMSP.credit_keep cr cri (NESKA.spa_pot P (NESK.sk_c k)) (NESKA.spa_pot P (NESK.sk_c ki)).
(* [comment removed for export] *)
Definition cells_ok (cells : list (Z * Z)) : Prop := Forall (fun c => sp - FR <= fst c /\ fst c + 8 <= sp) cells.

Local Ltac cut_facts INV :=
  pose proof INV as (Cq & ASTKq & SZq & MRTq & AMq & ILKq & IAWq & HHq & EAq & SKAq & Zq & EKq & DKq & CKq);
  pose proof AMq as (Mhq & MIq); pose proof ASTKq as (A16q & SLOq & SHIq & SPTq & SDEFq & SUPq).

