Lemma cinv_start cells M1 md1 : cells_ok cells ->
  mem_grows M M1 -> (forall i, 0 <= i < 2 ^ 64 -> ~ (sp - FR <= i < sp) -> M1 (Z_to_bv 64 i) = M (Z_to_bv 64 i)) ->
  Forall (fun c => L5.u64_at RSEGS M1 (fst c) (snd c)) cells ->
  ri_inv HI (NECS.eown en k ++ LBX) FF LK cr Aw M1 (vml_of md1) -> L5CA.amodel_ok Aw md1 -> model_rt model md1 ->
  cinv cells M1 md1 LK Aw cr k 0 0.
