(* [comment removed for export] *)
Lemma vis_top cells Mq mdq LKq Awq crq kq lo hi : cinv cells Mq mdq LKq Awq crq kq lo hi -> 1 <= en_n en ->
  let H := ahid Awq mdq in let MV := mrestrict H Mq in let eb := en_b en in let ed := en_b en + 24 * en_n en in
  0 < en_k en /\ 4096 <= eb /\ 4120 <= ed /\ ed <= sp - SCR /\ ed mod 8 = 0 /\ 24 <= ed - eb <= 100000
  /\ L5.writable RSEGS MV (ed - 24) 24 /\ (2147446784 + 17592186048512 <= ed - 24 \/ (ed - 24) + 24 <= 2147446784)
  /\ L5KA.zeros_at MV ((ed - 8) / 8 + SBL) 1
  /\ (ed <= ov \/ ov + 56 <= ed - 24)
  /\ (exists cn, 0 <= cn < 2 ^ 64 /\ L5.u64_at RSEGS MV (ed - 8) cn)
