(* [comment removed for export] *)
Lemma step_frame cells Mq mdq LKq Awq crq kq lo hi (fxq fx3 : FPState) Rq (pcq : Z) R3 (pc3 : Z) M3v wlo whi :
  cinv cells Mq mdq LKq Awq crq kq lo hi -> cells_ok cells ->
  msteps RSEGS (mst fxq Rq pcq (mrestrict (ahid Awq mdq) Mq)) (mst fx3 R3 pc3 M3v) -> mem_grows (mrestrict (ahid Awq mdq) Mq) M3v ->
  (forall i, 0 <= i < 2 ^ 64 -> ~ (wlo <= i < whi) -> M3v (Z_to_bv 64 i) = mrestrict (ahid Awq mdq) Mq (Z_to_bv 64 i)) ->
  sp - FR <= wlo -> whi <= sp -> Forall (fun c => whi <= fst c \/ fst c + 8 <= wlo) cells ->
  (forall M3 md3, cinv cells M3 md3 LKq Awq crq kq lo hi -> mrestrict (ahid Awq mdq) M3 = M3v -> ahid Awq md3 = ahid Awq mdq ->
      srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fx3) R3 pc3 M3 md3) K) ->
