(* [comment removed for export] *)
Lemma step_ro cells Mq mdq LKq Awq crq kq lo hi (fxq fx3 : FPState) Rq (pcq : Z) R3 (pc3 : Z) M3v :
  cinv cells Mq mdq LKq Awq crq kq lo hi ->
  msteps RSEGS (mst fxq Rq pcq (mrestrict (ahid Awq mdq) Mq)) (mst fx3 R3 pc3 M3v) -> mem_grows (mrestrict (ahid Awq mdq) Mq) M3v ->
  (forall i, 0 <= i < 2 ^ 64 -> M3v (Z_to_bv 64 i) = mrestrict (ahid Awq mdq) Mq (Z_to_bv 64 i)) ->
  (forall md3, cinv cells Mq md3 LKq Awq crq kq lo hi -> ahid Awq md3 = ahid Awq mdq -> srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fx3) R3 pc3 Mq md3) K) ->
