(* [comment removed for export] *)
Lemma step_start cells (fx fx1 : FPState) R1 (pc0 pc1 : Z) M1v :
  cells_ok cells ->
  msteps RSEGS (mst fx R pc0 (mrestrict (ahid Aw model) M)) (mst fx1 R1 pc1 M1v) -> mem_grows (mrestrict (ahid Aw model) M) M1v ->
  (forall i, 0 <= i < 2 ^ 64 -> ~ (sp - FR <= i < sp - FR + FR) -> M1v (Z_to_bv 64 i) = mrestrict (ahid Aw model) M (Z_to_bv 64 i)) ->
  Forall (fun c => L5.u64_at RSEGS M1v (fst c) (snd c)) cells ->
  (forall M1 md1, cinv cells M1 md1 LK Aw cr k 0 0 -> mrestrict (ahid Aw model) M1 = M1v -> ahid Aw md1 = ahid Aw model ->
      srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fx1) R1 pc1 M1 md1) K) ->
  srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fx) R pc0 M model) K.
