Section Calls.
Variable cells : list (Z * Z).
Hypothesis COK : cells_ok cells.
Hypothesis PMODE : NESKA.spa_mode P.

(* [comment removed for export] *)
Hypothesis PB : NESKA.push_back_specA RSEGS AD EE L ar HI P.
Lemma call_pb (lo hi ra pv : Z) (fxq : FPState) Rq Mq mdq LKq Awq crq kq :
  cinv cells Mq mdq LKq Awq crq kq lo hi -> 0 <= lo -> NESK.sk_z k + hi + 1 <= NESK.SMZ -> L5.ra_ok ra -> sp - FR <= pv -> pv + 1 <= sp ->
  getr Rq (reg 1) = Z_to_bv 64 ra -> getr Rq (reg 2) = Z_to_bv 64 (sp - FR) ->
  getr Rq (reg 3) = getr R (reg 3) -> getr Rq (reg 4) = getr R (reg 4) ->
  getr Rq (reg 10) = Z_to_bv 64 osk -> getr Rq (reg 11) = Z_to_bv 64 pv ->
  (forall (fx2 : FPState) R2 M2 md2 LK2 Aw2 cr2 k2, cinv cells M2 md2 LK2 Aw2 cr2 k2 (lo + 1) (hi + 1) -> regs_preserved Rq R2 ->
      srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fx2) R2 ra M2 md2) K) ->
