(* [comment removed for export] *)
Lemma call_wts (WTS : NECSA.write_timestamp_specA RSEGS AD EE L ar HI P) (lo hi ra : Z) (fxq : FPState) Rq Mq mdq LKq Awq crq kq :
  cinv cells Mq mdq LKq Awq crq kq lo hi -> 0 <= lo -> NESK.sk_z k + hi + 15 <= NESK.SMZ -> L5.ra_ok ra -> 3 <= h -> FR + 18432 <= SCR ->
  getr Rq (reg 1) = Z_to_bv 64 ra -> getr Rq (reg 2) = Z_to_bv 64 (sp - FR) ->
  getr Rq (reg 3) = getr R (reg 3) -> getr Rq (reg 4) = getr R (reg 4) ->
  getr Rq (reg 10) = Z_to_bv 64 ov ->
  (forall (fx2 : FPState) R2 M2 md2 LK2 Aw2 cr2 k2, cinv cells M2 md2 LK2 Aw2 cr2 k2 (lo + 6) (hi + 15) -> regs_preserved Rq R2 ->
      srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fx2) R2 ra M2 md2) K) ->
