(* [comment removed for export] *)
Lemma UPIECE n M1 model1 LK1 Aw1 x g1 cr1 (fx1 fx2 : FPState) R1 R2 (pc1 pc2 : Z) (M2v : mem) (Wp : Z -> Prop) :
  uinv n M1 model1 LK1 Aw1 x g1 cr1 ->
  msteps RSEGS (st fx1 R1 pc1 (mrestrict (ahid Aw1 model1) M1)) (st fx2 R2 pc2 M2v) ->
  mem_grows (mrestrict (ahid Aw1 model1) M1) M2v ->
  (forall a, 0 <= a < 2 ^ 64 -> ~ Wp a -> M2v (Z_to_bv 64 a) = mrestrict (ahid Aw1 model1) M1 (Z_to_bv 64 a)) ->
  (forall a, Wp a -> ~ ocell a /\ ufoot a) ->
  (forall (M3 : mem) model3,
      uinv n M3 model3 LK1 Aw1 x g1 cr1 ->
      ahid Aw1 model3 = ahid Aw1 model1 -> mrestrict (ahid Aw1 model1) M3 = M2v ->
      (forall a, 0 <= a < 2 ^ 64 -> ~ Wp a -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) -> mem_grows M1 M3 ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 pc2 M3 model3) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 pc1 M1 model1) K.
Proof using All.
