Lemma u_after BXa n M1 model1 LK1 Aw1 x g1 cr1 (M4 : mem) model4 LK4 Aw4 x4 g4 cr4 (SCRc n' : Z) (Wc : list L5.range) :
  uinv n M1 model1 LK1 Aw1 x g1 cr1 -> 0 <= SCRc -> sp - SCR <= spc - SCRc ->
  L5CA.ahpres L ar (BXa ++ LB) FF' spc SCRc Wc M1 M4 ->
  ri_inv HI (PM.vs_own x4 ++ LB) FF' LK4 cr4 Aw4 M4 (vml_of model4) -> L5CA.amodel_ok Aw4 model4 -> model_rt model1 model4 -> incl Aw1 Aw4 -> incl LK4 LK1 ->
  (forall rr a, In rr Wc -> L5.in_rng rr a -> ~ ocell a /\ ~ (F / 8 + SB <= a < F / 8 + SB + B / 8) /\ ~ PMST.dep AD a /\ ~ (65536 <= a < 1409024)) ->
  (forall a, aclient L ar LB FF sp SCR a -> L5.outside WT a -> L5.outside Wc a) ->
  kstr_at M4 os x4 -> txt_ok M4 x4 -> PQMA.ks_ok SM x4 g4 -> PM.vs_size x4 = PM.vs_size x0 + n' ->
  PMSP.credit_keep cr cr4 POT0 (PMSPA.scA L (PQMA.pot_ks HV SM x4 g4)) ->
  uinv n' M4 model4 LK4 Aw4 x4 g4 cr4
  /\ (forall a, spc <= a < sp -> L5.outside Wc a -> M4 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a))
